result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ics.py", "content": """"Minimal RFC 5545 iCalendar parser (stdlib only).

Handles:
- Line unfolding: CRLF (or LF) followed by a single space or tab
  continues the previous logical line.
- BEGIN:X / END:X nesting into a component tree of dicts.
- Property parameters: NAME;PARAM=VALUE;PARAM=V1,V2:value
- Text-value unescaping: \\n / \\N -> newline, \\, -> comma,
  \\; -> semicolon, \\\\ -> backslash.
"""

from __future__ import annotations

from typing import Any


class IcsError(ValueError):
    """Raised for malformed iCalendar input."""

    def __init__(self, message: str, line_number: int | None = None):
        self.line_number = line_number
        if line_number is not None:
            message = f"line {line_number}: {message}"
        super().__init__(message)


def _unfold(text: str) -> list[tuple[int, str]]:
    """Return list of (line_number, logical_line) with folded lines joined.

    line_number is the 1-based number of the *first* physical line of the
    logical line. A continuation must be CRLF/LF followed by exactly one
    space or tab (RFC 5545 §3.1).
    """
    if "\x00" in text:
        raise IcsError("NUL byte in input", 1)

    physical = text.splitlines()
    logical: list[tuple[int, str]] = []
    i = 0
    while i < len(physical):
        start_no = i + 1
        buf = [physical[i]]
        i += 1
        # A fold is LF/CRLF + one SP/HTAB. splitlines() ate the newline;
        # the next physical line beginning with exactly one SP/HTAB is a
        # continuation; that single whitespace char is removed.
        while i < len(physical) and (
            physical[i].startswith((" ", "\t"))
        ):
            buf.append(physical[i][1:])
            i += 1
        logical.append((start_no, "".join(buf)))
    return logical


def _split_name_params(head: str) -> tuple[str, dict[str, list[str]]]:
    """Split 'NAME;P=V;Q="a;b",c' into (NAME, params). Quote-aware."""
    name_parts: list[str] = []
    params: dict[str, list[str]] = {}
    param_name: str | None = None
    cur = []
    in_quotes = False
    i = 0

    def flush_value() -> None:
        nonlocal cur, param_name
        if param_name is None:
            name_parts.append("".join(cur))
        else:
            params.setdefault(param_name.upper(), []).append("".join(cur))
        cur = []

    while i < len(head):
        ch = head[i]
        if in_quotes:
            if ch == '"':
                in_quotes = False
            else:
                cur.append(ch)
        elif ch == '"':
            in_quotes = True
        elif ch == ";":
            flush_value()
            param_name = None  # next segment starts a new param name
        elif ch == "=" and param_name is None:
            param_name = "".join(cur).upper()
            cur = []
        elif ch == "," and param_name is not None:
            flush_value()
        elif ch == ":" and param_name is None:
            # end of the name/params section entirely
            break
        else:
            cur.append(ch)
        i += 1

    flush_value()

    rest = head[i:] if i < len(head) else ""
    name = name_parts[0] if name_parts else ""
    return name.upper(), params, rest


def _unescape(value: str) -> str:
    """RFC 5545 §3.3.11 TEXT unescaping."""
    out: list[str] = []
    i = 0
    while i < len(value):
        ch = value[i]
        if ch == "\\" and i + 1 < len(value):
            nxt = value[i + 1]
            if nxt in ("n", "N"):
                out.append("\n")
                i += 2
                continue
            if nxt in (",", ";", "\\"):
                out.append(nxt)
                i += 2
                continue
        out.append(ch)
        i += 1
    return "".join(out)


def parse(text: str) -> dict[str, Any]:
    """Parse iCalendar text into a component tree.

    Component shape:
        {
          "type": "VCALENDAR",
          "props": {"VERSION": [{"value": "2.0", "params": {...}}, ...]},
          "components": [ ...nested components... ],
        }
    """
    lines = _unfold(text)
    root: dict[str, Any] | None = None
    stack: list[dict[str, Any]] = []

    for lineno, raw in lines:
        if not raw.strip():
            continue  # tolerate blank lines

        head, _, value_part = raw.partition(":")
        name, params, trailing = _split_name_params(head)
        if trailing:
            # there was a ':' inside params section; rejoin remainder
            value_part = trailing + ":" + value_part if False else value_part

        if not name:
            raise IcsError(f"malformed content line: {raw!r}", lineno)

        if name == "BEGIN":
            comp = {
                "type": value_part.strip().upper(),
                "props": {},
                "components": [],
            }
            if root is None:
                root = comp
            else:
                if not stack:
                    raise IcsError(
                        f"component {comp['type']} outside of root component",
                        lineno,
                    )
                stack[-1]["components"].append(comp)
            stack.append(comp)
            continue

        if name == "END":
            want = value_part.strip().upper()
            if not stack:
                raise IcsError(f"END:{want} without matching BEGIN", lineno)
            comp = stack.pop()
            if comp["type"] != want:
                raise IcsError(
                    f"END:{want} does not match BEGIN:{comp['type']}",
                    lineno,
                )
            continue

        prop = {"value": _unescape(value_part), "params": params}
        stack_at = stack[-1]["props"] if stack else None
        if stack_at is None:
            raise IcsError(f"property {name} outside any component", lineno)
        stack_at.setdefault(name, []).append(prop)

    if root is None:
        raise IcsError("no BEGIN component found", 1)
    if stack:
        unclosed = stack[-1]
        last_lineno = lines[-1][0] if lines else 1
        raise IcsError(
            f"unterminated component BEGIN:{unclosed['type']}",
            last_lineno,
        )
    return root


def events(cal: dict[str, Any]) -> list[dict[str, Any]]:
    """Extract VEVENTs from a parsed calendar.

    Each returned event dict maps property names to lists of
    {"value": ..., "params": ...} entries, e.g.:
        {"SUMMARY": [{"value": "...", "params": {}}],
         "DTSTART": [{"value": "20240101T090000",
                      "params": {"TZID": ["America/New_York"]}}]}
    """
    found: list[dict[str, Any]] = []

    def walk(comp: dict[str, Any]) -> None:
        for sub in comp.get("components", []):
            if sub["type"] == "VEVENT":
                found.append(sub["props"])
            walk(sub)

    walk(cal)
    return found


# Convenience accessors ---------------------------------------------------

def first_prop(props: dict[str, Any], name: str) -> dict[str, Any] | None:
    """First occurrence of property `name`, or None."""
    occurrences = props.get(name.upper())
    return occurrences[0] if occurrences else None


def raw_value(props: dict[str, Any], name: str) -> str | None:
    """Raw (still-escaped) value of first occurrence of property `name`."""
    prop = first_prop(props, name)
    return prop["value"] if prop else None
